	ymaps.ready(init);

	function init() {
		let myMap = new ymaps.Map("map", {center: [55.567988, 37.603738], zoom: 12});
		myMap.controls.add("zoomControl").add("typeSelector").add("mapTools");
		let myPlacemark = new ymaps.Placemark([55.567988, 37.603738], {
				balloonContent: '<div style="background: white"><p><b>NOQO</b></p><p>Москва, Симферопольское шоссе 3А, оф.408</p><p><b>График работы:</b> пн-пт.: 9:00-18:00</p></div>',
			},
		);
		myMap.geoObjects.add(myPlacemark);
	}
