export  const agecheck = () => {
	const ageBtn = document.querySelector(".js-agecheck-ok");

	const ageCheck = document.querySelector(".js-agecheck");
	const ageCheckBlock = document.querySelector(".agecheck__block");


	if (localStorage.getItem("agecheck") !== "true") {
		ageCheck.style.display = "flex";
	}
	ageBtn?.addEventListener("click", function () {
		ageCheck.classList.add("agecheck_hidden");
		localStorage.setItem("agecheck", "true");
		setTimeout(() => {
			ageCheck.style.display = "none";
		}, 400);
	})
};
