"use strict";
export function circleAnimation() {
	let element = document.querySelector('.product__tastes');
	//if (element) {
		const cards = document.querySelectorAll('.tastes__card');
		let currentIndex = 0;

// Функция для добавления и удаления класса .active

		function cycleActiveClass() {
			// Убираем класс .active у текущего элемента
			cards[currentIndex].classList.remove('active');

			// Переходим к следующему элементу
			currentIndex = (currentIndex + 1) % cards.length;

			// Добавляем класс .active к следующему элементу
			cards[currentIndex].classList.add('active');
		}

// Запускаем цикл с интервалом в 1 секунду
	if (cards.length > 0) {
		setInterval(cycleActiveClass, 2000);
	}

// Инициализируем первый элемент с классом .active
		if (cards.length > 0) {
			cards[currentIndex].classList.add('active');
		}
	//}
}
